insert into public.weeks (week, phase, module, lectures, reading, case_exercise, deliverable, elective_slot) values
(1,'Core','Orientation','Browse the LBS MBA curriculum','The Personal MBA (Kaufman)','Set up your canvas; send a 360° survey to 5 colleagues','1-page why + 3 goals',false),
(2,'Core','Financial Accounting','Coursera: Intro to Financial Accounting (Wharton), weeks 1–2','Financial Intelligence (Berman & Knight)','Read the annual report of a listed company you know well (e.g. Tesco or Unilever)','3 statements summarised on 1 page',false),
(3,'Core','Financial Accounting','Wharton course, weeks 3–4','Accounting Made Simple (Piper)','Ratio analysis vs one competitor','Ratio spreadsheet + 5 findings',false),
(4,'Core','Corporate Finance','Damodaran Corporate Finance, sessions 1–6','Principles of Corporate Finance (Brealey, Myers, Allen) ch. 1–6','NPV / IRR of a new product launch','Project NPV model',false),
(5,'Core','Corporate Finance','Damodaran sessions 7–14','Brealey ch. 7–12 (risk, cost of capital)','HBS: Marriott Corporation: The Cost of Capital','WACC calculation + memo',false),
(6,'Core','Corporate Finance','Damodaran valuation sessions','The Little Book of Valuation (Damodaran)','DCF of the week-2 company','Full DCF + buy/hold/sell call',false),
(7,'Core','Data & Decisions','Khan Academy statistics','Naked Statistics (Wheelan)','Decision tree for a real choice you face','Decision tree + expected value',false),
(8,'Core','Data & Decisions','Khan Academy regression; Excel regression tutorials','How to Measure Anything (Hubbard)','HBS: Pilgrim Bank','Regression output + recommendations',false),
(9,'Core','Managerial Economics','MIT OCW 15.010','Microeconomics (Pindyck & Rubinfeld), selected','Demand, elasticity and pricing in your market','Pricing memo',false),
(10,'Core','Managerial Economics','MIT 15.010 (market structure, game theory)','The Art of Strategy (Dixit & Nalebuff)','Map the market structure of your industry','1-page industry economics memo',false),
(11,'Core','Macro & Global Economy','Yale: Financial Markets (Shiller), selected','Mishkin, selected chapters','How rates, inflation and FX hit your sector','Macro-risk memo',false),
(12,'Core','Review week','—','Reread notes','Midterm: one past case, 2 hrs, closed book','Graded midterm',false),
(13,'Core','Strategy','MIT OCW 15.900','Good Strategy Bad Strategy (Rumelt)','HBS: Cola Wars Continue: Coke and Pepsi','Five forces analysis',false),
(14,'Core','Strategy','MIT 15.900 continued','Playing to Win (Lafley & Martin)','HBS: Zara: Fast Fashion','Strategy cascade for your company',false),
(15,'Core','Strategy','LBS Think articles on strategy','Breaking Bad Habits (Vermeulen)','Write your company''s strategy kernel','2-page strategy memo',false),
(16,'Core','Marketing','Coursera: Wharton Marketing','Marketing Management (Kotler), selected','HBS: Dove: Evolution of a Brand','Segmentation + positioning map',false),
(17,'Core','Marketing','Wharton Marketing continued','How Brands Grow (Sharp)','Pricing + go-to-market plan for one product','1-page go-to-market plan',false),
(18,'Core','Operations','MIT OCW 15.761','The Goal (Goldratt)','HBS: Toyota Motor Manufacturing, U.S.A., Inc.','Process map with bottleneck',false),
(19,'Core','Operations','MIT 15.761 continued','The Toyota Way (Liker), selected','Map one real process in your business','Improvement plan',false),
(20,'Core','Org Behaviour & Leadership','Stanford GSB talks (YouTube)','Act Like a Leader, Think Like a Leader (Ibarra)','HBS: Heidi Roizen','Your network map',false),
(21,'Core','Org Behaviour & Leadership','Stanford GSB talks','The Five Dysfunctions of a Team (Lencioni)','HBS: Rob Parson at Morgan Stanley','360 results memo',false),
(22,'Core','Ethics & Responsibility','LBS Think on purpose and responsibility','Prosperity (Colin Mayer)','Stakeholder map for your company','1-page purpose statement',false),
(23,'Core','Integration','—','—','HBS: Warren E. Buffett, 2005','3-page board recommendation',false),
(24,'Core','Review week','—','Reread notes','Final core exam: unseen case, 3 hrs','Graded final; choose electives',false),
(25,'Electives','Growth Marketing','Coursera: Marketing Analytics (UVA Darden)','Hacking Growth (Ellis & Brown)','Map your acquisition-to-retention funnel','Funnel map + biggest drop-off',true),
(26,'Electives','Growth Marketing','Marketing Analytics continued','Lean Analytics (Croll & Yoskovitz)','Design 3 growth experiments for the drop-off','Experiment plan',true),
(27,'Electives','Growth Marketing','Google Skillshop: Google Analytics','Monetizing Innovation (Ramanujam & Tacke)','Willingness-to-pay survey with 20 people','Pricing recommendation',true),
(28,'Electives','AI & Tech Strategy','Coursera: AI For Everyone (DeepLearning.AI)','Power and Prediction (Agrawal, Gans, Goldfarb)','Mark where AI changes your company''s 10 biggest decisions','AI opportunity map',true),
(29,'Electives','AI & Tech Strategy','Stanford GSB / MIT Sloan AI strategy talks','Competing in the Age of AI (Iansiti & Lakhani)','Compare with an AI-native competitor','2-page competitive memo',true),
(30,'Electives','AI & Tech Strategy','Platform strategy talks (Parker, Van Alstyne)','Platform Revolution (Parker, Van Alstyne, Choudary)','AI adoption business case','Business case for your boss',true),
(31,'Electives','Data & Analytics','Kaggle Learn: SQL + Pandas','Storytelling with Data (Knaflic)','Answer a real business question with data','1-page analysis + chart',true),
(32,'Electives','Sales & Business Development','HubSpot Academy sales courses','The Challenger Sale; SPIN Selling','Shadow 2 sales calls or role-play; discovery script','Sales playbook for one offer',true),
(33,'Electives','Negotiation & Influence','Coursera: Successful Negotiation (Michigan)','Getting to Yes; Influence (Cialdini)','2 role plays + 1 real negotiation','Prep sheets + debrief',true),
(34,'Electives','Entrepreneurship','YC Startup School','The Mom Test (Fitzpatrick)','10 customer interviews on one problem','Idea brief',true),
