(38,'Capstone','Problem & customer','—','—','Synthesise interviews','Customer persona',false),
(39,'Capstone','Market & strategy','—','—','Market sizing','Market sizing model',false),
(40,'Capstone','Market & strategy','—','—','Five forces + strategy kernel; book 3 pitch reviewers','Strategy kernel',false),
